class ParallelSmaRsiStrategies(QCAlgorithm):

    RED_CONSECUTIVE_DAYS = 3

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy_closes = RollingWindow[float](101)
        self.aapl_closes = RollingWindow[float](self.RED_CONSECUTIVE_DAYS + 1)
        self.aapl_rsi = self.RSI(
            self.symbols["AAPL"], 14, MovingAverageType.Wilders, Resolution.Daily
        )

        self.a_lot = 0
        self.b_lot = 0
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        spy_bar = data.Bars.get(self.symbols["SPY"])
        aapl_bar = data.Bars.get(self.symbols["AAPL"])

        if spy_bar is not None:
            self.spy_closes.Add(float(spy_bar.Close))

        if aapl_bar is not None:
            if self.aapl_closes.Count > 0:
                if float(aapl_bar.Close) < self.aapl_closes[0]:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_closes.Add(float(aapl_bar.Close))

        if any(data.Bars.get(symbol) is None for symbol in self.symbols.values()):
            return

        spy_close = float(data.Bars[self.symbols["SPY"]].Close)
        aapl_close = float(data.Bars[self.symbols["AAPL"]].Close)

        # Sells are evaluated before buys.
        if self.a_lot > 0 and self.spy_closes.IsReady:
            sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
            sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
            if self.spy_closes[1] >= sma_yesterday and spy_close < sma_today:
                self.MarketOrder(self.symbols["SPY"], -self.a_lot)

        if self.b_lot > 0 and self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.symbols["AAPL"], -self.b_lot)

        if self.a_lot == 0 and self.spy_closes.IsReady:
            sma_today = sum(self.spy_closes[i] for i in range(100)) / 100.0
            sma_yesterday = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
            if self.spy_closes[1] <= sma_yesterday and spy_close > sma_today:
                quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["SPY"], quantity)

        if self.b_lot == 0 and self.aapl_rsi.IsReady:
            if self.aapl_red_streak >= self.RED_CONSECUTIVE_DAYS:
                if self.Portfolio.CashBook["USD"].Amount >= 20_000:
                    quantity = int(20_000 / aapl_close)
                    if quantity > 0:
                        self.MarketOrder(self.symbols["AAPL"], quantity)

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if orderEvent.Status != OrderStatus.Filled:
            return

        if orderEvent.Symbol == self.symbols["SPY"]:
            self.a_lot += orderEvent.FillQuantity
            if self.a_lot < 0:
                self.a_lot = 0

        elif orderEvent.Symbol == self.symbols["AAPL"]:
            self.b_lot += orderEvent.FillQuantity
            if self.b_lot < 0:
                self.b_lot = 0
