class IndependentSpyAndAaplStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = deque(maxlen=101)
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data: Slice):
        # Keep market-state quantities current for every ticker that has a bar.
        if data.Bars.ContainsKey(self.spy):
            self.spy_closes.append(data.Bars[self.spy].Close)

        if data.Bars.ContainsKey(self.aapl):
            aapl_close = data.Bars[self.aapl].Close

            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        # Keep private lots aligned with corporate-action share adjustments.
        for symbol in self.symbols:
            if data.Splits.ContainsKey(symbol):
                split_factor = data.Splits[symbol].SplitFactor
                if split_factor != 0:
                    if symbol == self.spy and self.strategy_a_lot > 0:
                        self.strategy_a_lot = int(round(
                            self.strategy_a_lot / split_factor
                        ))
                    elif symbol == self.aapl and self.strategy_b_lot > 0:
                        self.strategy_b_lot = int(round(
                            self.strategy_b_lot / split_factor
                        ))

        # All rules are skipped unless every subscribed ticker has today's bar.
        if not all(data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        # The SMA cross requires both today's and yesterday's fully formed SMA.
        if len(self.spy_closes) < 101 or not self.aapl_rsi.IsReady:
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        closes = list(self.spy_closes)
        yesterday_spy_close = closes[-2]
        sma_today = sum(closes[-100:]) / 100.0
        sma_yesterday = sum(closes[-101:-1]) / 100.0

        spy_crosses_above_sma = (
            yesterday_spy_close <= sma_yesterday and
            spy_close > sma_today
        )
        spy_crosses_below_sma = (
            yesterday_spy_close >= sma_yesterday and
            spy_close < sma_today
        )

        # Evaluate all sells before any buys.
        if self.strategy_a_lot > 0 and spy_crosses_below_sma:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above_sma:
            quantity = int(floor(
                (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
            ))
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 1:
            if self.Portfolio.Cash >= 20_000:
                quantity = int(floor(20_000 / aapl_close))
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity
